/**
 * The pure decisions the surface generator makes, separated from the file it writes.
 *
 * Everything here is a total function over a specification's own text, so the generated registry can be
 * regenerated byte-identically and each rule can be tested without a network call or a temp directory.
 */

/** Which pinned specification a row came from. Also the prefix of every generated surface name. */
export type JumpcloudSpec = "v1" | "v2" | "insights";

/** How a collection is walked, decided from the operation's own declared parameters. */
export type JumpcloudPagination = "limit-skip" | "limit-offset" | "token" | "limit-only" | "none";

/** The path prefix each specification's operations hang off, appended to their origin. */
const SPEC_PREFIX: Readonly<Record<JumpcloudSpec, string>> = {
  insights: "/insights/directory/v1",
  v1: "/api",
  v2: "/api/v2",
};

/**
 * Convert an OpenAPI `operationId` into the kebab-case half of a surface name.
 *
 * Splits camelCase and snake_case, lowercases, and collapses every run of non-alphanumerics to a single
 * hyphen, so `getSystemInsightsApps` and `get_system_insights_apps` reach the same name. A stable, derived
 * name is what lets the generator's output be diffed across a specification bump.
 *
 * @param operationId the specification's own operation identifier
 * @returns the kebab-case name fragment, with no leading or trailing hyphen
 * @internal
 */
export function kebabOperationId({ operationId }: { operationId: string }): string {
  return operationId
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/[^a-zA-Z0-9]+/g, "-")
    .toLowerCase()
    .replace(/^-+|-+$/g, "");
}

/**
 * The full surface name a caller passes instead of a URL.
 *
 * @param spec which pinned specification the operation came from
 * @param operationId the specification's own operation identifier
 * @returns the collision-tested `<spec>-<operation>` name
 * @internal
 */
export function surfaceName({ spec, operationId }: { spec: JumpcloudSpec; operationId: string }): string {
  return `${spec}-${kebabOperationId({ operationId })}`;
}

/**
 * The normalized path an operation is reached at — the pinned prefix plus the specification's own path key.
 *
 * Concatenated rather than templated so the path key survives verbatim; a generator that rewrote path keys
 * would silently diverge from the document the digest pins.
 *
 * @param spec which pinned specification the operation came from
 * @param pathKey the specification's own path, including its `{brace}` parameters
 * @returns the normalized path, with no origin
 * @internal
 */
export function normalizedPath({ spec, pathKey }: { spec: JumpcloudSpec; pathKey: string }): string {
  return `${SPEC_PREFIX[spec]}${pathKey}`;
}

/**
 * Decide how a collection is paged from the parameter names the operation declares.
 *
 * Order matters: an operation declaring both `skip` and a cursor is walked by offset, because that is what
 * JumpCloud's own guidance describes for the Directory API. `limit` alone is a cap rather than a walk, and
 * is reported as such so a reducer never treats one page as a census.
 *
 * @param parameterNames every query parameter the operation declares
 * @returns the pagination shape this operation is walked with
 * @internal
 */
export function paginationOf({ parameterNames }: { parameterNames: readonly string[] }): JumpcloudPagination {
  if (parameterNames.includes("skip")) {
    return "limit-skip";
  }
  if (parameterNames.includes("offset")) {
    return "limit-offset";
  }
  if (parameterNames.some((name) => /token|cursor|search_after/i.test(name))) {
    return "token";
  }
  if (parameterNames.includes("limit")) {
    return "limit-only";
  }
  return "none";
}

/**
 * The atlas kind an operation contributes to, taken from the first segment of its path.
 *
 * The provider's own vocabulary rather than an invented one: `systeminsights` stays `systeminsights` and
 * `password-vault` stays `password-vault`, so a reader who knows the console knows the kind.
 *
 * @param pathKey the specification's own path key
 * @returns the first path segment, or `root` for a path with none
 * @internal
 */
export function kindOf({ pathKey }: { pathKey: string }): string {
  // `split` always yields at least one element, so the first is present; it is EMPTY for a path with no
  // segment, which is the case `root` names.
  const first = pathKey.replace(/^\/+/, "").split("/")[0]!;
  if (first === "") {
    return "root";
  }
  return first;
}
